try:
    import termios, tty, select, os

    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)

    def set_raw(raw):
        tty.setraw(fd) if raw else termios.tcsetattr(fd, termios.TCSADRAIN, old)

    set_raw(True)
    sys.stdout.write("\x1b[?25l")  # hide cursor
    while True:

input.new_string:
try:
    import termios, tty, select, os

    fd = sys.stdin.fileno()
    raw = False
    try:
        old = termios.tcgetattr(fd)
        tty.setraw(fd)
        raw = True
    except (termios.error, AttributeError, OSError):
        pass  # stdin is a pipe/file — fall back to line-buffered input

    sys.stdout.write("\x1b[?25l")  # hide cursor
    while True:

